import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, ToolCallInput } from 'claude-code'

import type { LoadedRules, RuleSet } from '../types'
import {
  STARTER_FILE,
  analyzeBash,
  commandVerdict,
  defaultRules,
  emptyRules,
  filePathOf,
  globParts,
  mergeRules,
  newFileVerdict,
  parseRules,
  pinEveryOf,
  pinText,
  protectVerdict,
  report,
  resolvePath,
  shellNameMatches,
  shouldPin,
} from './logic'
import type { PathFacts, ShellTarget, Verdict } from './logic'

const COMMAND = 'house-rules'
const RULES_FILE = '.claude/house-rules.json'
const GLOBAL_NAME = '~/.claude/house-rules.json'
const ERROR_TOAST_MS = 10_000
/** Lets a compaction install its summary before the pins are appended after it. */
const COMPACT_SETTLE_MS = 500
/** Paths one Bash call is checked for at most; each costs a stat or two. */
const MAX_TARGETS = 64
const GUARDED_TOOLS = new Set(['Edit', 'MultiEdit', 'Write', 'NotebookEdit', 'Bash'])

const loaded = atom({ plugin: 'house-rules', key: 'loaded' } as const, null)
const blocks = atom({ plugin: 'house-rules', key: 'blocks' } as const, {})
const prompts = atom({ plugin: 'house-rules', key: 'prompts' } as const, 0)
const toasted = atom({ plugin: 'house-rules', key: 'toasted' } as const, [])
const pinPending = atom({ plugin: 'house-rules', key: 'pinPending' } as const, false)

type Settings = { usesDefaults: boolean; readsGlobal: boolean }

/** Where the rules come from and what paths are relative to. */
type Places = { root: string; roots: string[]; cwd: string; home: string | undefined; project: string; global: string | null }

async function placesOf($: EngineInterface, settings: Settings): Promise<Places> {
  const root = await $.session.root()
  const cwd = await $.session.cwd()
  const home = await $.env.get('HOME')
  const realRoot = await $.fs
    .stat(root, { resolve: true })
    .then(stat => stat.realPath)
    .catch(() => undefined)
  const project = `${root}/${RULES_FILE}`
  const global = settings.readsGlobal && home !== undefined ? `${home}/${RULES_FILE}` : null

  return {
    root,
    roots: realRoot === undefined || realRoot === root ? [root] : [root, realRoot],
    cwd,
    home,
    project,
    global: global === project ? null : global,
  }
}

/** A missing file is the normal case, not an error: it reads as null. */
async function mtimeOf($: EngineInterface, path: string): Promise<number | null> {
  return $.fs
    .stat(path)
    .then(stat => stat.mtimeMs)
    .catch(() => null)
}

async function toastNewErrors($: EngineInterface, errors: readonly string[]): Promise<void> {
  const seen = await read($, toasted)
  const fresh = errors.filter(error => !seen.includes(error))

  if (fresh.length === 0) {
    return
  }

  await update($, toasted, list => [...(list ?? []), ...fresh])
  const more = fresh.length === 1 ? '' : ` (+${fresh.length - 1} more)`
  $.ui.toast(`house-rules: ${fresh[0]}${more}. That entry is ignored; /house-rules lists all.`, { timeoutMs: ERROR_TOAST_MS })
}

/** The rules in force: read again only when a rules file's mtime, the root or the settings changed. */
async function rulesOf($: EngineInterface, settings: Settings, places: Places): Promise<LoadedRules> {
  const projectMtime = await mtimeOf($, places.project)
  const globalMtime = places.global === null ? null : await mtimeOf($, places.global)
  const key = [places.root, projectMtime, globalMtime, settings.usesDefaults, settings.readsGlobal].join('|')
  const cached = await read($, loaded)

  if (cached !== null && cached.key === key) {
    return cached
  }

  const sources = [
    { path: places.global, mtime: globalMtime, name: GLOBAL_NAME },
    { path: places.project, mtime: projectMtime, name: RULES_FILE },
  ]
  const sets: RuleSet[] = []
  const files: string[] = []
  const errors: string[] = []

  for (const source of sources) {
    if (source.path === null || source.mtime === null) {
      continue
    }

    const text = await $.fs.read(source.path).catch((error: unknown) => {
      errors.push(`${source.name}: cannot be read (${error instanceof Error ? error.message : String(error)})`)

      return null
    })

    if (text === null) {
      continue
    }

    const parsed = parseRules(text, source.name)
    errors.push(...parsed.errors)

    if (parsed.isReadable) {
      sets.push(parsed.rules)
      files.push(source.name)
    }
  }

  const isDefault = files.length === 0 && settings.usesDefaults
  const next: LoadedRules = {
    key,
    rules: isDefault ? defaultRules() : files.length === 0 ? emptyRules() : mergeRules(sets),
    files,
    errors,
    isDefault,
  }

  await update($, loaded, () => next)
  await toastNewErrors($, errors)

  return next
}

async function factsOf($: EngineInterface, path: string, isRemoval: boolean): Promise<PathFacts> {
  const stat = await $.fs.stat(path, { resolve: true }).catch(() => null)
  const realPath = stat?.realPath

  return realPath === undefined || realPath === path
    ? { path, exists: stat !== null, isRemoval }
    : { path, realPath, exists: true, isRemoval }
}

/** A target like `/work/*.txt` becomes the files the shell would expand it to, plus itself. */
async function expandTargets($: EngineInterface, targets: readonly ShellTarget[]): Promise<ShellTarget[]> {
  const expanded: ShellTarget[] = []

  for (const target of targets) {
    expanded.push(target)
    const parts = target.hasGlob && target.intoDir === undefined ? globParts(target.path) : null

    if (parts === null) {
      continue
    }

    const entries = await $.fs.list(parts.dir).catch(() => [])

    for (const entry of entries) {
      if (shellNameMatches(parts.pattern, entry.name)) {
        expanded.push({ path: `${parts.dir === '/' ? '' : parts.dir}/${entry.name}`, mayCreate: target.mayCreate, hasGlob: false })
      }
    }
  }

  return expanded.slice(0, MAX_TARGETS)
}

async function judgeBash($: EngineInterface, rules: RuleSet, places: Places, command: string): Promise<Verdict | null> {
  const analysis = analyzeBash(command, places.cwd, places.home)
  const byCommand = commandVerdict(rules, analysis.segments)

  if (byCommand !== null || (rules.protect.length === 0 && rules.noNewFiles.length === 0)) {
    return byCommand
  }

  for (const target of await expandTargets($, analysis.targets)) {
    if (target.intoDir !== undefined) {
      const kind = await $.fs
        .stat(target.intoDir)
        .then(stat => stat.kind)
        .catch(() => null)

      if (kind !== 'dir') {
        continue
      }
    }

    const facts = await factsOf($, target.path, !target.mayCreate)
    const verdict = protectVerdict(rules, facts, places.roots) ?? (target.mayCreate ? newFileVerdict(rules, facts, places.roots) : null)

    if (verdict !== null) {
      return verdict
    }
  }

  return null
}

/** The rule a tool call breaks, or null. Tools that write nothing are let through without a file system call. */
async function judge($: EngineInterface, e: ToolCallInput, settings: Settings): Promise<Verdict | null> {
  if (!GUARDED_TOOLS.has(e.tool)) {
    return null
  }

  const places = await placesOf($, settings)
  const { rules } = await rulesOf($, settings, places)
  const input = e as unknown as Readonly<Record<string, unknown>>

  if (e.tool === 'Bash') {
    return judgeBash($, rules, places, typeof input.command === 'string' ? input.command : '')
  }

  const written = filePathOf(e.tool, input)

  if (written === null || (rules.protect.length === 0 && rules.noNewFiles.length === 0)) {
    return null
  }

  const facts = await factsOf($, resolvePath(places.cwd, written, places.home), false)

  return protectVerdict(rules, facts, places.roots) ?? (e.tool === 'Write' ? newFileVerdict(rules, facts, places.roots) : null)
}

/** The pinned rules as the model reads them, or null when there are none. */
async function pinsOf($: EngineInterface, settings: Settings): Promise<{ text: string; every: number } | null> {
  const current = await rulesOf($, settings, await placesOf($, settings))

  return current.rules.pin.length === 0 ? null : { text: pinText(current.rules.pin, current.files), every: pinEveryOf(current.rules) }
}

async function appendPinsAfterCompaction($: EngineInterface, settings: Settings): Promise<void> {
  if (!(await read($, pinPending))) {
    return
  }

  const pins = await pinsOf($, settings)

  if (pins === null) {
    await update($, pinPending, () => false)

    return
  }

  const stored = await $.session.append({ message: { type: 'user', content: [{ type: 'text', text: pins.text }] } }).catch((error: unknown) => {
    $.ui.log(`house-rules: could not append the pinned rules after compaction (${error instanceof Error ? error.message : String(error)}); they go with the next prompt`)

    return null
  })

  if (stored !== null && !('deny' in stored && stored.deny !== undefined)) {
    await update($, pinPending, () => false)
  }
}

async function initFile($: EngineInterface, settings: Settings): Promise<string> {
  const places = await placesOf($, settings)

  if (await $.fs.exists(places.project)) {
    return `${RULES_FILE} already exists; house-rules leaves it as it is. Run /house-rules to see what it holds.`
  }

  await $.fs.write(places.project, STARTER_FILE)
  await update($, loaded, () => null)
  await rulesOf($, settings, places)

  return `Wrote ${RULES_FILE} with example rules. Edit it: changes apply on the next tool call.\n\n${STARTER_FILE}`
}

async function showRules($: EngineInterface, settings: Settings): Promise<string> {
  const current = await rulesOf($, settings, await placesOf($, settings))

  return report(current, await read($, blocks), await read($, prompts))
}

export const register: Register = (on, options) => {
  const settings: Settings = { usesDefaults: options.defaultRules !== false, readsGlobal: options.globalFile !== false }

  on('session.start', async ($, e, next) => {
    await $.command.register({ name: COMMAND, description: 'Show the house rules in force and what they blocked; init writes a starter file', argumentHint: '[init]' })
    await rulesOf($, settings, await placesOf($, settings))

    return next(e)
  })

  on('tool.call', async ($, e, next) => {
    const verdict = await judge($, e, settings)

    if (verdict === null) {
      return next(e)
    }

    await update($, blocks, map => ({ ...map, [verdict.ruleId]: (map?.[verdict.ruleId] ?? 0) + 1 }))

    return { deny: verdict.reason }
  })

  on('prompt.submit', async ($, e, next) => {
    const count = await update($, prompts, n => (n ?? 0) + 1)
    const pins = await pinsOf($, settings)
    const isAfterCompaction = await read($, pinPending)

    if (pins === null || !(isAfterCompaction || shouldPin(count, pins.every))) {
      return next(e)
    }

    await update($, pinPending, () => false)

    return next({ ...e, context: [...(e.context ?? []), pins.text] })
  })

  on('session.compact', async ($, e, next) => {
    const result = await next(e)

    if (result.skip === undefined && e.trigger !== 'precompute' && e.agentId === undefined) {
      await update($, pinPending, () => true)
      $.clock.after(COMPACT_SETTLE_MS, () => {
        void appendPinsAfterCompaction($, settings)
      })
    }

    return result
  })

  on('command.run', { command: COMMAND }, async ($, e) => {
    const isInit = e.args.trim().toLowerCase() === 'init'

    return { text: isInit ? await initFile($, settings) : await showRules($, settings) }
  })
}

