import type { CommandRule, LoadedRules, NoNewFilesRule, ProtectRule, RuleSet } from '../types'

export const DEFAULT_PIN_EVERY = 10
/** A brace glob expands to at most this many plain globs; more is a typo or an attack on the matcher. */
const MAX_BRACE_EXPANSIONS = 256
const PROJECT_FILE = '.claude/house-rules.json'

export const GENERIC_WHY = {
  protect: 'this path is protected by the house rules',
  noNewFiles: 'new files like this are not wanted in this repo',
  commands: 'this command is not allowed in this repo',
} as const

const KNOWN_FIELDS = ['protect', 'noNewFiles', 'commands', 'pin', 'pinEvery'] as const

export const emptyRules = (): RuleSet => ({ protect: [], noNewFiles: [], commands: [], pin: [], pinEvery: null })

// ---------------------------------------------------------------- paths

/** Folds `.`, `..` and repeated slashes; keeps a leading slash. */
export const normalizePath = (path: string): string => {
  const isAbsolute = path.startsWith('/')
  const parts: string[] = []

  for (const part of path.split('/')) {
    if (part === '' || part === '.') {
      continue
    }

    if (part === '..') {
      if (parts.length > 0 && parts[parts.length - 1] !== '..') {
        parts.pop()
      } else if (!isAbsolute) {
        parts.push('..')
      }

      continue
    }

    parts.push(part)
  }

  const joined = parts.join('/')

  return isAbsolute ? `/${joined}` : joined === '' ? '.' : joined
}

/** An absolute path for `path` as a shell in `base` would read it; `~/` needs `home`. */
export const resolvePath = (base: string, path: string, home?: string): string => {
  if (path.startsWith('/')) {
    return normalizePath(path)
  }

  if ((path === '~' || path.startsWith('~/')) && home !== undefined) {
    return normalizePath(`${home}/${path.slice(1)}`)
  }

  return normalizePath(`${base}/${path}`)
}

/** The path relative to the first root it lies under, '' for a root itself, null when outside all. */
export const relativeTo = (roots: readonly string[], absolute: string): string | null => {
  const path = normalizePath(absolute)

  for (const root of roots) {
    const clean = normalizePath(root)

    if (path === clean) {
      return ''
    }

    const prefix = clean === '/' ? '/' : `${clean}/`

    if (path.startsWith(prefix)) {
      return path.slice(prefix.length)
    }
  }

  return null
}

export const baseName = (path: string): string => path.slice(path.lastIndexOf('/') + 1)

const dirName = (path: string): string => {
  const cut = path.lastIndexOf('/')

  return cut <= 0 ? (cut === 0 ? '/' : '.') : path.slice(0, cut)
}

/** 'a/b/c' → ['a', 'a/b', 'a/b/c']; '/x/y' → ['/x', '/x/y']: the path and every folder above it. */
const prefixesOf = (path: string): string[] => {
  const isAbsolute = path.startsWith('/')
  const parts = path.split('/').filter(part => part !== '')

  return parts.map((_, index) => `${isAbsolute ? '/' : ''}${parts.slice(0, index + 1).join('/')}`)
}

// ---------------------------------------------------------------- globs

const splitTopLevel = (body: string): string[] => {
  const parts: string[] = []
  let depth = 0
  let start = 0

  for (let index = 0; index < body.length; index++) {
    const char = body[index]

    if (char === '\\') {
      index++
    } else if (char === '{') {
      depth++
    } else if (char === '}') {
      depth--
    } else if (char === ',' && depth === 0) {
      parts.push(body.slice(start, index))
      start = index + 1
    }
  }

  parts.push(body.slice(start))

  return parts
}

/** `{a,b}c` → ['ac', 'bc'], nested groups too; a group with no comma stays literal. */
export const expandBraces = (glob: string): string[] => {
  let depth = 0
  let start = -1

  for (let index = 0; index < glob.length; index++) {
    const char = glob[index]

    if (char === '\\') {
      index++
    } else if (char === '{') {
      if (depth === 0) {
        start = index
      }

      depth++
    } else if (char === '}' && depth > 0) {
      depth--

      if (depth === 0) {
        const parts = splitTopLevel(glob.slice(start + 1, index))

        if (parts.length > 1) {
          const head = glob.slice(0, start)
          const tail = glob.slice(index + 1)

          return parts.flatMap(part => expandBraces(`${head}${part}${tail}`)).slice(0, MAX_BRACE_EXPANSIONS + 1)
        }
      }
    }
  }

  return [glob]
}

/** Why a glob cannot be used, or null when it can. */
export const globProblem = (glob: string): string | null => {
  if (glob.trim() === '') {
    return 'is empty'
  }

  let braces = 0
  let isInClass = false

  for (let index = 0; index < glob.length; index++) {
    const char = glob[index]

    if (char === '\\') {
      index++
    } else if (isInClass) {
      isInClass = char !== ']'
    } else if (char === '[') {
      isInClass = true
      // A ']' right after '[' (or '[!') is a member, not the end.
      if (glob[index + 1] === '!' || glob[index + 1] === '^') {
        index++
      }

      if (glob[index + 1] === ']') {
        index++
      }
    } else if (char === '{') {
      braces++
    } else if (char === '}') {
      braces--

      if (braces < 0) {
        return 'has a "}" with no "{" before it'
      }
    }
  }

  if (isInClass) {
    return 'has a "[" that is never closed'
  }

  if (braces > 0) {
    return 'has a "{" that is never closed'
  }

  const expanded = expandBraces(glob)

  if (expanded.length > MAX_BRACE_EXPANSIONS) {
    return `expands to more than ${MAX_BRACE_EXPANSIONS} patterns`
  }

  for (const one of expanded) {
    if (one.split('/').some(segment => segment.includes('**') && segment !== '**')) {
      return 'uses "**" inside a name; write "**/" for any folders or "*" for part of a name'
    }
  }

  return null
}

const escapeRegExp = (text: string): string => text.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&')

/** One path segment of a glob as a regular expression source. */
const segmentSource = (segment: string): string => {
  let out = ''

  for (let index = 0; index < segment.length; index++) {
    const char = segment[index] ?? ''

    if (char === '\\') {
      out += escapeRegExp(segment[index + 1] ?? '')
      index++
    } else if (char === '*') {
      out += '[^/]*'
    } else if (char === '?') {
      out += '[^/]'
    } else if (char === '[') {
      const close = segment.indexOf(']', index + 2)

      if (close === -1) {
        out += '\\['
        continue
      }

      let body = segment.slice(index + 1, close)
      const isNegated = body.startsWith('!') || body.startsWith('^')

      if (isNegated) {
        body = body.slice(1)
      }

      out += `[${isNegated ? '^' : ''}${body.replace(/\\/g, '\\\\').replace(/]/g, '\\]')}]`
      index = close
    } else {
      out += escapeRegExp(char)
    }
  }

  return out
}

const plainGlobSource = (glob: string): string => {
  const segments = glob.split('/')

  return segments
    .map((segment, index) => {
      const isLast = index === segments.length - 1

      if (segment === '**') {
        return isLast ? '.*' : '(?:[^/]+/)*'
      }

      return segmentSource(segment) + (isLast ? '' : '/')
    })
    .join('')
}

const cleanGlob = (glob: string): string => glob.trim().replace(/^(\.\/)+/, '').replace(/(.)\/+$/, '$1')

const compiled = new Map<string, RegExp>()

/** The whole glob, braces expanded, as one anchored regular expression. */
export const globRegExp = (glob: string, ignoreCase = false): RegExp => {
  const key = `${ignoreCase ? 'i' : ''}:${glob}`
  const known = compiled.get(key)

  if (known !== undefined) {
    return known
  }

  const sources = expandBraces(cleanGlob(glob)).slice(0, MAX_BRACE_EXPANSIONS).map(plainGlobSource)
  const made = new RegExp(`^(?:${sources.join('|')})$`, ignoreCase ? 'i' : '')
  compiled.set(key, made)

  return made
}

/**
 * Whether a glob covers an absolute path, gitignore style: a glob with no
 * slash matches a file or folder name at any depth, one with a slash is
 * relative to the project root, one starting with '/' is an absolute path,
 * and a glob that matches a folder covers everything inside it.
 */
export const globCovers = (glob: string, absolute: string, roots: readonly string[], ignoreCase = false): boolean => {
  const clean = cleanGlob(glob)
  const pattern = globRegExp(clean, ignoreCase)
  const path = normalizePath(absolute)

  if (clean.startsWith('/')) {
    return prefixesOf(path).some(prefix => pattern.test(prefix))
  }

  const relative = relativeTo(roots, path)

  if (clean.includes('/')) {
    return relative !== null && relative !== '' && prefixesOf(relative).some(prefix => pattern.test(prefix))
  }

  if (relative === null) {
    return pattern.test(baseName(path))
  }

  return relative.split('/').some(segment => segment !== '' && pattern.test(segment))
}

/** A shell glob in one file name (`*.txt`), as a shell expands it: `*` skips names starting with a dot. */
export const shellNameMatches = (pattern: string, name: string): boolean => {
  if (name.startsWith('.') && !pattern.startsWith('.')) {
    return false
  }

  return new RegExp(`^${segmentSource(pattern)}$`).test(name)
}

// ---------------------------------------------------------------- rules file

const REPORT_WORDS = new Set(['SUMMARY', 'SUMMARIES', 'REPORT', 'REPORTS', 'NOTES', 'IMPLEMENTATION', 'ANALYSIS', 'ANALYSES', 'CHANGES', 'PLAN', 'PLANS'])

/**
 * Whether a file name reads as a report Claude writes for itself:
 * FINAL_SUMMARY.md, implementation-plan.md, TestReport.md. Whole words only,
 * so explanation.md and reporting-api.md stay allowed.
 */
export const isReportName = (name: string): boolean => {
  if (!/\.md$/i.test(name)) {
    return false
  }

  const words = name
    .slice(0, -'.md'.length)
    .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
    .split(/[^A-Za-z0-9]+/)

  return words.some(word => REPORT_WORDS.has(word.toUpperCase()))
}

export const DEFAULT_SOURCE = 'built-in default'
export const DEFAULT_RULE_ID = 'noNewFiles:report-files'

/** The one rule that holds with no rules file: no new report-style markdown outside docs/. */
export const defaultRules = (): RuleSet => ({
  ...emptyRules(),
  noNewFiles: [
    {
      kind: 'noNewFiles',
      id: DEFAULT_RULE_ID,
      match: { type: 'report-words' },
      except: ['docs/**', '.claude/**', 'README.md', 'CHANGELOG.md', 'CONTRIBUTING.md'],
      why: 'report-style markdown (SUMMARY, REPORT, NOTES, IMPLEMENTATION, ANALYSIS, CHANGES, PLAN) is not wanted outside docs/',
      source: DEFAULT_SOURCE,
    },
  ],
})

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value)

const describe = (value: unknown): string => (Array.isArray(value) ? 'a list' : value === null ? 'null' : typeof value)

type Entry = { pattern: string; why: string; except: string[] }

/** One `protect` / `noNewFiles` / `commands` entry: a bare string, or an object with its key and an optional why. */
const entryOf = (
  value: unknown,
  where: string,
  key: 'glob' | 'match',
  allowsExcept: boolean,
  fallbackWhy: string,
  errors: string[],
): Entry | null => {
  if (typeof value === 'string') {
    return { pattern: value, why: fallbackWhy, except: [] }
  }

  if (!isRecord(value)) {
    errors.push(`${where} must be a string or an object with "${key}", got ${describe(value)}`)

    return null
  }

  const allowed = new Set([key, 'why', ...(allowsExcept ? ['except'] : [])])

  for (const field of Object.keys(value)) {
    if (!field.startsWith('$') && !allowed.has(field)) {
      errors.push(`${where} has an unknown field "${field}" (allowed: ${[...allowed].join(', ')})`)
    }
  }

  const pattern = value[key]

  if (typeof pattern !== 'string') {
    errors.push(`${where}.${key} must be a string`)

    return null
  }

  const why = value.why

  if (why !== undefined && (typeof why !== 'string' || why.trim() === '')) {
    errors.push(`${where}.why must be a non-empty string`)
  }

  const except: string[] = []
  const rawExcept = value.except

  if (rawExcept !== undefined) {
    if (!Array.isArray(rawExcept)) {
      errors.push(`${where}.except must be a list of globs`)
    } else {
      rawExcept.forEach((item: unknown, index) => {
        const problem = typeof item === 'string' ? globProblem(item) : 'is not a string'

        if (problem === null && typeof item === 'string') {
          except.push(item)
        } else {
          errors.push(`${where}.except[${index}] ${problem ?? ''}`.trim())
        }
      })
    }
  }

  return { pattern, why: typeof why === 'string' && why.trim() !== '' ? why.trim() : fallbackWhy, except }
}

const listOf = (data: Record<string, unknown>, field: string, source: string, errors: string[]): unknown[] => {
  const value = data[field]

  if (value === undefined) {
    return []
  }

  if (!Array.isArray(value)) {
    errors.push(`${source}: "${field}" must be a list, got ${describe(value)}`)

    return []
  }

  return value
}

/** `isReadable` is false when the file is not a JSON object at all: then it counts as no file. */
export type Parsed = { rules: RuleSet; errors: string[]; isReadable: boolean }

/** Reads one rules file. Bad entries are reported and skipped; the good ones still apply. */
export const parseRules = (text: string, source: string): Parsed => {
  const rules = emptyRules()
  const errors: string[] = []
  let data: unknown

  try {
    data = JSON.parse(text)
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error)

    return { rules, errors: [`${source}: not valid JSON (${message})`], isReadable: false }
  }

  if (!isRecord(data)) {
    return { rules, errors: [`${source}: must be a JSON object, got ${describe(data)}`], isReadable: false }
  }

  for (const field of Object.keys(data)) {
    if (!field.startsWith('$') && !(KNOWN_FIELDS as readonly string[]).includes(field)) {
      errors.push(`${source}: unknown field "${field}" (known: ${KNOWN_FIELDS.join(', ')})`)
    }
  }

  listOf(data, 'protect', source, errors).forEach((value, index) => {
    const where = `${source}: protect[${index}]`
    const entry = entryOf(value, where, 'glob', false, GENERIC_WHY.protect, errors)
    const problem = entry === null ? null : globProblem(entry.pattern)

    if (entry !== null && problem !== null) {
      errors.push(`${where} "${entry.pattern}" ${problem}`)
    } else if (entry !== null) {
      rules.protect.push({ kind: 'protect', id: `protect:${entry.pattern}`, glob: entry.pattern, why: entry.why, source })
    }
  })

  listOf(data, 'noNewFiles', source, errors).forEach((value, index) => {
    const where = `${source}: noNewFiles[${index}]`
    const entry = entryOf(value, where, 'glob', true, GENERIC_WHY.noNewFiles, errors)
    const problem = entry === null ? null : globProblem(entry.pattern)

    if (entry !== null && problem !== null) {
      errors.push(`${where} "${entry.pattern}" ${problem}`)
    } else if (entry !== null) {
      rules.noNewFiles.push({
        kind: 'noNewFiles',
        id: `noNewFiles:${entry.pattern}`,
        match: { type: 'glob', glob: entry.pattern },
        except: entry.except,
        why: entry.why,
        source,
      })
    }
  })

  listOf(data, 'commands', source, errors).forEach((value, index) => {
    const where = `${source}: commands[${index}]`
    const entry = entryOf(value, where, 'match', false, GENERIC_WHY.commands, errors)

    if (entry === null) {
      return
    }

    try {
      new RegExp(entry.pattern)
      rules.commands.push({ kind: 'commands', id: `commands:${entry.pattern}`, match: entry.pattern, why: entry.why, source })
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error)
      errors.push(`${where}.match is not a valid regular expression (${message})`)
    }
  })

  listOf(data, 'pin', source, errors).forEach((value, index) => {
    if (typeof value === 'string' && value.trim() !== '') {
      rules.pin.push(value.trim())
    } else {
      errors.push(`${source}: pin[${index}] must be a non-empty string`)
    }
  })

  const every = data.pinEvery

  if (every !== undefined) {
    if (typeof every === 'number' && Number.isInteger(every) && every >= 0) {
      rules.pinEvery = every
    } else {
      errors.push(`${source}: pinEvery must be a whole number of prompts (0 pins only after compaction)`)
    }
  }

  return { rules, errors, isReadable: true }
}

const byId = <T extends { id: string }>(lists: readonly T[][]): T[] => {
  const merged = new Map<string, T>()

  for (const list of lists) {
    for (const rule of list) {
      merged.set(rule.id, rule)
    }
  }

  return [...merged.values()]
}

/** Merges rule sets in order; a later set (the project's) wins a rule with the same pattern, and pinEvery. */
export const mergeRules = (sets: readonly RuleSet[]): RuleSet => ({
  protect: byId(sets.map(set => set.protect)),
  noNewFiles: byId(sets.map(set => set.noNewFiles)),
  commands: byId(sets.map(set => set.commands)),
  pin: [...new Set(sets.flatMap(set => set.pin))],
  pinEvery: sets.reduce<number | null>((value, set) => set.pinEvery ?? value, null),
})

export const pinEveryOf = (rules: RuleSet): number => rules.pinEvery ?? DEFAULT_PIN_EVERY

// ---------------------------------------------------------------- shell

/** Index of the ')' closing the '(' just before `from`, quotes respected; the end when none. */
const closingParen = (text: string, from: number): number => {
  let depth = 1
  let quote: string | null = null

  for (let index = from; index < text.length; index++) {
    const char = text[index]

    if (quote !== null) {
      if (char === '\\' && quote === '"') {
        index++
      } else if (char === quote) {
        quote = null
      }
    } else if (char === '\\') {
      index++
    } else if (char === '"' || char === "'") {
      quote = char
    } else if (char === '(') {
      depth++
    } else if (char === ')') {
      depth--

      if (depth === 0) {
        return index
      }
    }
  }

  return text.length
}

const HEREDOC = /^<<(-?)\s*(['"]?)([A-Za-z_][\w-]*)\2/

/**
 * Splits a shell command into the simple commands it runs: at `&&`, `||`,
 * `;`, `|`, `&` and newlines outside quotes. Heredoc bodies are skipped, and
 * the insides of `$(...)` and backticks are added as commands of their own.
 */
export const splitSegments = (command: string): string[] => {
  const segments: string[] = []
  const nested: string[] = []
  const heredocs: { delimiter: string; isIndented: boolean }[] = []
  let current = ''
  let quote: '"' | "'" | null = null
  let index = 0

  const flush = () => {
    if (current.trim() !== '') {
      segments.push(current.trim())
    }

    current = ''
  }

  while (index < command.length) {
    const char = command[index] ?? ''
    const pair = command.slice(index, index + 2)

    if (quote === "'") {
      current += char
      quote = char === "'" ? null : quote
      index++
      continue
    }

    if (char === '\\') {
      current += pair
      index += 2
      continue
    }

    if (pair === '$(' && command[index + 2] !== '(') {
      const end = closingParen(command, index + 2)
      nested.push(...splitSegments(command.slice(index + 2, end)))
      current += command.slice(index, end + 1)
      index = end + 1
      continue
    }

    if (char === '`') {
      const found = command.indexOf('`', index + 1)
      const end = found === -1 ? command.length : found
      nested.push(...splitSegments(command.slice(index + 1, end)))
      current += command.slice(index, end + 1)
      index = end + 1
      continue
    }

    if (quote === '"') {
      current += char
      quote = char === '"' ? null : quote
      index++
      continue
    }

    if (char === '"' || char === "'") {
      quote = char
      current += char
      index++
      continue
    }

    const heredoc = HEREDOC.exec(command.slice(index))

    if (heredoc !== null && command[index + 2] !== '<') {
      heredocs.push({ delimiter: heredoc[3] ?? '', isIndented: heredoc[1] === '-' })
      current += heredoc[0]
      index += heredoc[0].length
      continue
    }

    if (char === '\n') {
      flush()
      index++

      for (const { delimiter, isIndented } of heredocs.splice(0)) {
        while (index < command.length) {
          const lineEnd = command.indexOf('\n', index)
          const end = lineEnd === -1 ? command.length : lineEnd
          const line = command.slice(index, end)
          index = end + 1

          if ((isIndented ? line.replace(/^\t+/, '') : line) === delimiter) {
            break
          }
        }
      }

      continue
    }

    if (pair === '&&' || pair === '||') {
      flush()
      index += 2
      continue
    }

    const isRedirectAmp = char === '&' && (command[index - 1] === '>' || command[index + 1] === '>')

    if (char === ';' || char === '|' || (char === '&' && !isRedirectAmp)) {
      flush()
      index++
      continue
    }

    current += char
    index++
  }

  flush()

  return [...segments, ...nested]
}

/** A shell word with its quotes removed; `hasGlob` / `hasVariable` say whether the shell would rewrite it. */
export type Word = { text: string; isOperator: boolean; isQuoted: boolean; hasGlob: boolean; hasVariable: boolean }

const word = (text: string, flags: Partial<Omit<Word, 'text'>> = {}): Word => ({
  text,
  isOperator: false,
  isQuoted: false,
  hasGlob: false,
  hasVariable: false,
  ...flags,
})

/** The words of one simple command; redirection operators (`>`, `2>>`, `&>`, `>&2`) are words of their own. */
export const wordsOf = (segment: string): Word[] => {
  const words: Word[] = []
  let text = ''
  let isStarted = false
  let isQuoted = false
  let hasGlob = false
  let hasVariable = false
  let index = 0

  const push = () => {
    if (isStarted) {
      words.push(word(text, { isQuoted, hasGlob, hasVariable }))
    }

    text = ''
    isStarted = false
    isQuoted = false
    hasGlob = false
    hasVariable = false
  }

  while (index < segment.length) {
    const char = segment[index] ?? ''

    if (/\s/.test(char) || char === '(' || char === ')') {
      push()
      index++
    } else if (char === "'") {
      const found = segment.indexOf("'", index + 1)
      const end = found === -1 ? segment.length : found
      text += segment.slice(index + 1, end)
      isStarted = true
      isQuoted = true
      index = end + 1
    } else if (char === '"') {
      let cursor = index + 1

      while (cursor < segment.length && segment[cursor] !== '"') {
        if (segment[cursor] === '\\' && cursor + 1 < segment.length) {
          cursor++
        } else if (segment[cursor] === '$' || segment[cursor] === '`') {
          hasVariable = true
        }

        text += segment[cursor] ?? ''
        cursor++
      }

      isStarted = true
      isQuoted = true
      index = cursor + 1
    } else if (char === '\\') {
      text += segment[index + 1] ?? ''
      isStarted = true
      index += 2
    } else if (char === '$' && segment[index + 1] === '(') {
      const end = closingParen(segment, index + 2)
      text += segment.slice(index, end + 1)
      isStarted = true
      hasVariable = true
      index = end + 1
    } else if (char === '`') {
      const found = segment.indexOf('`', index + 1)
      const end = found === -1 ? segment.length : found
      text += segment.slice(index, end + 1)
      isStarted = true
      hasVariable = true
      index = end + 1
    } else if (char === '>' || char === '<') {
      let operator = ''

      if (isStarted && !isQuoted && /^(\d+|&)$/.test(text)) {
        operator = text
        text = ''
        isStarted = false
      } else {
        push()
      }

      let cursor = index

      while (cursor < segment.length && (segment[cursor] === '>' || segment[cursor] === '<')) {
        cursor++
      }

      operator += segment.slice(index, cursor)

      if (segment[cursor] === '|' && operator.endsWith('>')) {
        operator += '|'
        cursor++
      }

      if (segment[cursor] === '&') {
        const duplicate = /^&(\d+|-)/.exec(segment.slice(cursor))
        const taken = duplicate === null ? '&' : duplicate[0]
        operator += taken
        cursor += taken.length
      }

      words.push(word(operator, { isOperator: true }))
      index = cursor
    } else {
      if (char === '*' || char === '?' || char === '[') {
        hasGlob = true
      }

      if (char === '$') {
        hasVariable = true
      }

      text += char
      isStarted = true
      index++
    }
  }

  push()

  return words.filter(one => one.isOperator || one.isQuoted || (one.text !== '{' && one.text !== '}'))
}

const SPECIAL_FILES = /^\/dev\/(null|stdout|stderr|tty|fd\/\d+)$/

type Redirect = { operator: string; target: Word }

/** The command's own words, and what its redirections point at. */
const splitRedirects = (words: readonly Word[]): { argv: Word[]; redirects: Redirect[] } => {
  const argv: Word[] = []
  const redirects: Redirect[] = []

  for (let index = 0; index < words.length; index++) {
    const current = words[index]

    if (current === undefined) {
      continue
    }

    if (!current.isOperator) {
      argv.push(current)
      continue
    }

    const isDuplicate = /&(\d+|-)$/.test(current.text)
    const target = words[index + 1]

    if (!isDuplicate && target !== undefined && !target.isOperator) {
      redirects.push({ operator: current.text, target })
      index++
    }
  }

  return { argv, redirects }
}

const WRAPPER_VALUE_OPTIONS: Readonly<Record<string, readonly string[]>> = {
  sudo: ['-u', '-g', '-C', '-D', '-h', '-p', '-U'],
  doas: ['-u', '-C'],
  env: ['-u', '-C', '-S'],
  nice: ['-n'],
  ionice: ['-c', '-n', '-p'],
  timeout: ['-s', '-k'],
  stdbuf: ['-i', '-o', '-e'],
  command: [],
  builtin: [],
  nohup: [],
  time: [],
  exec: ['-a'],
}

const isAssignment = (one: Word): boolean => !one.isQuoted && /^[A-Za-z_][A-Za-z0-9_]*=/.test(one.text)

/** Drops leading `VAR=value` words and wrappers like `sudo`, `env`, `nice -n 5`, `timeout 10`. */
export const stripWrappers = (argv: readonly Word[]): Word[] => {
  let rest = [...argv]

  for (;;) {
    const head = rest[0]

    if (head === undefined) {
      return rest
    }

    if (isAssignment(head)) {
      rest = rest.slice(1)
      continue
    }

    const name = baseName(head.text)
    const valueOptions = WRAPPER_VALUE_OPTIONS[name]

    if (valueOptions === undefined) {
      return rest
    }

    let index = 1

    while (index < rest.length) {
      const current = rest[index]

      if (current === undefined || !(current.text.startsWith('-') || (name === 'env' && isAssignment(current)))) {
        break
      }

      index += valueOptions.includes(current.text) ? 2 : 1

      if (current.text === '--') {
        break
      }
    }

    if (name === 'timeout') {
      index++
    }

    rest = rest.slice(index)
  }
}

/** The operands of a command: words that are not options, nor the values of `valueOptions`; all after `--`. */
const operandsOf = (args: readonly Word[], valueOptions: readonly string[] = []): Word[] => {
  const operands: Word[] = []
  let isPastOptions = false

  for (let index = 0; index < args.length; index++) {
    const current = args[index]

    if (current === undefined) {
      continue
    }

    if (isPastOptions || !current.text.startsWith('-') || current.text === '-') {
      operands.push(current)
    } else if (current.text === '--') {
      isPastOptions = true
    } else if (valueOptions.includes(current.text)) {
      index++
    }
  }

  return operands
}

const optionValue = (args: readonly Word[], names: readonly string[]): Word | undefined => {
  const index = args.findIndex(current => names.includes(current.text))

  return index === -1 ? undefined : args[index + 1]
}

/** A path the command writes, deletes or moves; `intoDir` means "only if that path is a folder". */
export type RawTarget = { word: Word; mayCreate: boolean; intoDir?: Word }

const copyLike = (args: readonly Word[], valueOptions: readonly string[], movesSources: boolean): RawTarget[] => {
  const operands = operandsOf(args, valueOptions)
  const named = optionValue(args, ['-t', '--target-directory'])
  const sources = named === undefined ? operands.slice(0, -1) : operands
  const destination = named ?? operands[operands.length - 1]

  if (destination === undefined || sources.length === 0) {
    return []
  }

  const moved = movesSources ? sources.map(source => ({ word: source, mayCreate: false })) : []
  const intoDir = sources.map(source => ({
    word: word(baseName(source.text.replace(/\/+$/, '')), { hasGlob: source.hasGlob, hasVariable: source.hasVariable }),
    mayCreate: true,
    intoDir: destination,
  }))
  const asFile = named === undefined && sources.length === 1 ? [{ word: destination, mayCreate: true }] : []

  return [...moved, ...asFile, ...intoDir]
}

/** `-i`, `-i.bak`, `-Ei`, `--in-place`: the bundled flags before the `i` are the ones each tool takes without a value. */
const isInPlace = (args: readonly Word[], bundled: RegExp): boolean =>
  args.some(current => current.text === '--in-place' || current.text.startsWith('--in-place=') || bundled.test(current.text))

const SED_IN_PLACE = /^-[nErsuz]*i/
const PERL_IN_PLACE = /^-[pnlaws0-9]*i/
/** A perl option that ends in `e` (`-e`, `-pe`) takes the script as the next word; `-ie` is `-i` with suffix `e`. */
const PERL_SCRIPT_OPTION = /^-[A-Za-hj-z0-9]*[eE]$/

const sedTargets = (args: readonly Word[]): RawTarget[] => {
  if (!isInPlace(args, SED_IN_PLACE)) {
    return []
  }

  // BSD sed spells "no backup" as `-i ''`: that empty word is the suffix, not the script.
  const cleaned = args.filter((current, index) => !(current.isQuoted && current.text === '' && args[index - 1]?.text === '-i'))
  const operands = operandsOf(cleaned, ['-e', '--expression', '-f', '--file', '-l'])
  const hasScriptOption = cleaned.some(current => ['-e', '--expression', '-f', '--file'].includes(current.text))

  return (hasScriptOption ? operands : operands.slice(1)).map(current => ({ word: current, mayCreate: false }))
}

const perlTargets = (args: readonly Word[]): RawTarget[] => {
  if (!isInPlace(args, PERL_IN_PLACE)) {
    return []
  }

  const operands: Word[] = []
  let hasScript = false

  for (let index = 0; index < args.length; index++) {
    const current = args[index]

    if (current === undefined) {
      continue
    }

    if (PERL_SCRIPT_OPTION.test(current.text)) {
      hasScript = true
      index++
    } else if (!current.text.startsWith('-')) {
      operands.push(current)
    }
  }

  return (hasScript ? operands : operands.slice(1)).map(current => ({ word: current, mayCreate: false }))
}

const gitTargets = (args: readonly Word[]): RawTarget[] => {
  let index = 0

  while (index < args.length && (args[index]?.text ?? '').startsWith('-')) {
    index += ['-C', '-c', '--git-dir', '--work-tree'].includes(args[index]?.text ?? '') ? 2 : 1
  }

  const sub = args[index]?.text
  const rest = args.slice(index + 1)

  switch (sub) {
    case 'rm':
      return operandsOf(rest).map(current => ({ word: current, mayCreate: false }))
    case 'mv':
      return copyLike(rest, [], true)
    case 'restore':
      return operandsOf(rest, ['-s', '--source']).map(current => ({ word: current, mayCreate: false }))
    case 'checkout': {
      const dashes = rest.findIndex(current => current.text === '--')

      return dashes === -1 ? [] : rest.slice(dashes + 1).map(current => ({ word: current, mayCreate: false }))
    }
    default:
      return []
  }
}

/** What one command (wrappers already stripped) writes, deletes or moves, by its name. */
const commandTargets = (argv: readonly Word[]): RawTarget[] => {
  const name = baseName(argv[0]?.text ?? '')
  const args = argv.slice(1)
  const each = (list: Word[], mayCreate: boolean): RawTarget[] => list.map(current => ({ word: current, mayCreate }))

  switch (name) {
    case 'rm':
    case 'unlink':
    case 'rmdir':
      return each(operandsOf(args), false)
    case 'shred':
      return each(operandsOf(args, ['-n', '-s', '--iterations', '--size']), false)
    case 'touch':
      return each(operandsOf(args, ['-r', '-t', '-d', '--reference', '--date']), true)
    case 'truncate':
      return each(operandsOf(args, ['-s', '-r', '--size', '--reference']), true)
    case 'tee':
      return each(operandsOf(args), true)
    case 'mv':
      return copyLike(args, ['-t', '--target-directory', '-S', '--suffix'], true)
    case 'cp':
    case 'ln':
      return copyLike(args, ['-t', '--target-directory', '-S', '--suffix'], false)
    case 'install':
      return copyLike(args, ['-t', '--target-directory', '-m', '--mode', '-o', '--owner', '-g', '--group', '-S', '--suffix'], false)
    case 'rsync':
      return copyLike(args, ['-e', '--rsh', '--exclude', '--include'], false)
    case 'sed':
    case 'gsed':
      return sedTargets(args)
    case 'perl':
      return perlTargets(args)
    case 'dd':
      return args.filter(current => current.text.startsWith('of=')).map(current => ({ word: { ...current, text: current.text.slice('of='.length) }, mayCreate: true }))
    case 'git':
      return gitTargets(args)
    default:
      return []
  }
}

const SHELLS = new Set(['bash', 'sh', 'zsh', 'dash', 'ksh'])
/** How deep `bash -c "eval '...'"` is read before giving up. */
const MAX_NESTING = 3

/** A path a Bash command touches, absolute; `intoDir` set means it counts only when that folder exists. */
export type ShellTarget = { path: string; mayCreate: boolean; hasGlob: boolean; intoDir?: string }

/** One simple command as typed, and with its wrappers and redirections taken off. */
export type ShellSegment = { raw: string; plain: string }

export type ShellAnalysis = { segments: ShellSegment[]; targets: ShellTarget[] }

/** The commands a Bash call runs and the paths it writes, `cd` followed from `cwd`. */
export const analyzeBash = (command: string, cwd: string, home?: string, depth = 0): ShellAnalysis => {
  const segments: ShellSegment[] = []
  const targets: ShellTarget[] = []
  let base = cwd

  for (const raw of splitSegments(command)) {
    const { argv: words, redirects } = splitRedirects(wordsOf(raw))
    const argv = stripWrappers(words)
    const name = baseName(argv[0]?.text ?? '')
    segments.push({ raw, plain: argv.map(current => current.text).join(' ') })

    const place = (current: Word): string | null =>
      current.hasVariable || current.text === '' ? null : resolvePath(base, current.text, current.isQuoted ? undefined : home)

    for (const { operator, target } of redirects) {
      const path = operator.includes('>') && !SPECIAL_FILES.test(target.text) ? place(target) : null

      if (path !== null) {
        targets.push({ path, mayCreate: true, hasGlob: target.hasGlob })
      }
    }

    if (name === 'cd' || name === 'pushd') {
      const to = operandsOf(argv.slice(1))[0]
      const next = to === undefined ? (home ?? null) : to.text === '-' ? null : place(to)
      base = next ?? base
      continue
    }

    if (depth < MAX_NESTING && SHELLS.has(name)) {
      const script = optionValue(argv, ['-c'])

      if (script !== undefined) {
        const inner = analyzeBash(script.text, base, home, depth + 1)
        segments.push(...inner.segments)
        targets.push(...inner.targets)
      }

      continue
    }

    if (depth < MAX_NESTING && name === 'eval') {
      const inner = analyzeBash(argv.slice(1).map(current => current.text).join(' '), base, home, depth + 1)
      segments.push(...inner.segments)
      targets.push(...inner.targets)
      continue
    }

    for (const target of commandTargets(argv)) {
      const path = place(target.word)

      if (path === null) {
        continue
      }

      if (target.intoDir === undefined) {
        targets.push({ path, mayCreate: target.mayCreate, hasGlob: target.word.hasGlob })
        continue
      }

      const folder = place(target.intoDir)

      if (folder !== null) {
        targets.push({ path: `${folder}/${baseName(path)}`, mayCreate: target.mayCreate, hasGlob: target.word.hasGlob, intoDir: folder })
      }
    }
  }

  return { segments, targets }
}

/** The folder and name pattern of a target with a glob in its last part only; null when the folder itself has one. */
export const globParts = (path: string): { dir: string; pattern: string } | null => {
  const dir = dirName(path)

  return /[*?[]/.test(dir) ? null : { dir, pattern: baseName(path) }
}

// ---------------------------------------------------------------- verdicts

export type Verdict = { ruleId: string; reason: string }

/** What a path is: its spelling, where it really lands (links followed) and whether it exists. */
export type PathFacts = { path: string; realPath?: string; exists: boolean; isRemoval?: boolean }

const shown = (path: string, roots: readonly string[]): string => {
  const relative = relativeTo(roots, path)

  return relative === null || relative === '' ? path : relative
}

const fileOfRules = (source: string): string => (source === DEFAULT_SOURCE ? PROJECT_FILE : source)

export const protectReason = (rule: ProtectRule, path: string, roots: readonly string[]): string =>
  `Blocked by house rules: ${shown(path, roots)} is protected (${rule.why}). Do not edit, move or delete it. ` +
  `If the task really needs that, stop and ask the user: they can change it themselves or edit the rule in ${fileOfRules(rule.source)}.`

export const newFileReason = (rule: NoNewFilesRule, path: string, roots: readonly string[]): string =>
  `Blocked by house rules: do not create ${shown(path, roots)} (${rule.why}). ` +
  'Put what you meant to write in your reply to the user, or into an existing file the task is about. ' +
  `If the user asked for this file, tell them it is blocked by ${fileOfRules(rule.source)}.`

export const commandReason = (rule: CommandRule, segment: string): string =>
  `Blocked by house rules: \`${segment}\` matches /${rule.match}/ (${rule.why}). Run the command this rule asks for instead; do not work around it with another spelling.`

/** The fixed folders a glob starts with: 'migrations/applied/**' → 'migrations/applied'; '' when it starts with a wildcard. */
const literalPrefixes = (glob: string): string[] =>
  expandBraces(cleanGlob(glob)).map(one => {
    const parts = one.split('/')
    const fixed: string[] = []

    for (const part of parts) {
      if (/[*?[\\]/.test(part)) {
        break
      }

      fixed.push(part)
    }

    return fixed.join('/')
  })

/** Whether deleting or moving `path` takes a protected path inside it with it (anchored globs only). */
const holdsProtected = (glob: string, path: string, roots: readonly string[]): boolean => {
  const clean = cleanGlob(glob)

  if (!clean.includes('/')) {
    return false
  }

  const inside = clean.startsWith('/') ? normalizePath(path) : relativeTo(roots, path)

  if (inside === null) {
    return false
  }

  return literalPrefixes(clean).some(prefix => inside === '' || inside === '/' || prefix.startsWith(`${inside}/`))
}

export const protectVerdict = (rules: RuleSet, facts: PathFacts, roots: readonly string[]): Verdict | null => {
  const spellings = facts.realPath === undefined ? [facts.path] : [facts.path, facts.realPath]

  for (const rule of rules.protect) {
    const isCovered = spellings.some(path => globCovers(rule.glob, path, roots))
    const isHeld = facts.isRemoval === true && spellings.some(path => holdsProtected(rule.glob, path, roots))

    if (isCovered || isHeld) {
      return { ruleId: rule.id, reason: protectReason(rule, facts.path, roots) }
    }
  }

  return null
}

const newFileMatches = (rule: NoNewFilesRule, path: string, roots: readonly string[]): boolean =>
  rule.match.type === 'glob' ? globCovers(rule.match.glob, path, roots) : isReportName(baseName(path))

/** A file that does not exist yet, inside the project, matching a noNewFiles rule and none of its exceptions. */
export const newFileVerdict = (rules: RuleSet, facts: PathFacts, roots: readonly string[]): Verdict | null => {
  if (facts.exists || relativeTo(roots, facts.path) === null) {
    return null
  }

  for (const rule of rules.noNewFiles) {
    const isExcepted = rule.except.some(glob => globCovers(glob, facts.path, roots))

    if (!isExcepted && newFileMatches(rule, facts.path, roots)) {
      return { ruleId: rule.id, reason: newFileReason(rule, facts.path, roots) }
    }
  }

  return null
}

export const commandVerdict = (rules: RuleSet, segments: readonly ShellSegment[]): Verdict | null => {
  for (const rule of rules.commands) {
    const pattern = new RegExp(rule.match)
    const hit = segments.find(segment => pattern.test(segment.raw) || pattern.test(segment.plain))

    if (hit !== undefined) {
      return { ruleId: rule.id, reason: commandReason(rule, hit.raw) }
    }
  }

  return null
}

/** The path a file tool writes, by the tool's own argument name; null for tools that write nothing. */
export const filePathOf = (tool: string, input: Readonly<Record<string, unknown>>): string | null => {
  const value = tool === 'NotebookEdit' ? input.notebook_path : ['Edit', 'MultiEdit', 'Write'].includes(tool) ? input.file_path : undefined

  return typeof value === 'string' && value !== '' ? value : null
}

// ---------------------------------------------------------------- pins

/** Pins go out on the first prompt and every `every` prompts after it; 0 means only after a compaction. */
export const shouldPin = (promptNumber: number, every: number): boolean => every > 0 && promptNumber >= 1 && (promptNumber - 1) % every === 0

export const pinText = (pins: readonly string[], files: readonly string[]): string =>
  `House rules for this project (from ${files.join(' and ')}; they still apply, whatever came since):\n` +
  pins.map(pin => `- ${pin}`).join('\n')

// ---------------------------------------------------------------- /house-rules

const blockedText = (count: number): string => (count === 0 ? '' : `  · blocked ${count}×`)

const sourceText = (source: string, files: readonly string[]): string => (files.length > 1 ? `  [${source}]` : '')

/** What /house-rules prints: every rule with its file and its blocks this session, then the errors. */
export const report = (loaded: LoadedRules, blocks: Readonly<Record<string, number>>, prompts: number): string => {
  const { rules, files, errors } = loaded
  const lines: string[] = []
  const count = rules.protect.length + rules.noNewFiles.length + rules.commands.length

  if (loaded.isDefault) {
    lines.push('No rules file, so the built-in default is on.')
  } else if (files.length === 0) {
    lines.push('No rules file and the built-in default is off: nothing is enforced.')
  } else {
    lines.push(`${count} rule${count === 1 ? '' : 's'} from ${files.join(', ')}`)
  }

  if (rules.protect.length > 0) {
    lines.push('', 'protect (no edit, move or delete)')

    for (const rule of rules.protect) {
      lines.push(`  ${rule.glob} — ${rule.why}${sourceText(rule.source, files)}${blockedText(blocks[rule.id] ?? 0)}`)
    }
  }

  if (rules.noNewFiles.length > 0) {
    lines.push('', 'noNewFiles (no new files)')

    for (const rule of rules.noNewFiles) {
      const pattern = rule.match.type === 'glob' ? rule.match.glob : '*.md named SUMMARY, REPORT, NOTES, IMPLEMENTATION, ANALYSIS, CHANGES or PLAN'
      const except = rule.except.length === 0 ? '' : ` except ${rule.except.join(', ')}`

      lines.push(`  ${pattern}${except} — ${rule.why}${sourceText(rule.source, files)}${blockedText(blocks[rule.id] ?? 0)}`)
    }
  }

  if (rules.commands.length > 0) {
    lines.push('', 'commands (blocked in Bash, each part of a chain)')

    for (const rule of rules.commands) {
      lines.push(`  /${rule.match}/ — ${rule.why}${sourceText(rule.source, files)}${blockedText(blocks[rule.id] ?? 0)}`)
    }
  }

  if (rules.pin.length > 0) {
    const every = pinEveryOf(rules)
    const cadence = every === 0 ? 'after each compaction' : `every ${every} prompts and after each compaction`
    lines.push('', `pin (${cadence}; ${prompts} prompt${prompts === 1 ? '' : 's'} so far)`)
    lines.push(...rules.pin.map(pin => `  - ${pin}`))
  }

  if (errors.length > 0) {
    lines.push('', 'errors (these entries are ignored)')
    lines.push(...errors.map(error => `  ${error}`))
  }

  if (files.length === 0) {
    lines.push('', 'Run /house-rules init to write a starter .claude/house-rules.json.')
  }

  return lines.join('\n')
}

