export type ProtectRule = { kind: 'protect'; id: string; glob: string; why: string; source: string }

/** A glob the user wrote, or the built-in report-file test, which matches whole words of the name. */
export type NewFileMatch = { type: 'glob'; glob: string } | { type: 'report-words' }

export type NoNewFilesRule = { kind: 'noNewFiles'; id: string; match: NewFileMatch; except: string[]; why: string; source: string }

export type CommandRule = { kind: 'commands'; id: string; match: string; why: string; source: string }

export type Rule = ProtectRule | NoNewFilesRule | CommandRule

export type RuleSet = {
  protect: ProtectRule[]
  noNewFiles: NoNewFilesRule[]
  commands: CommandRule[]
  pin: string[]
  /** Prompts between two pin injections; null while no file set it. */
  pinEvery: number | null
}

export type LoadedRules = {
  /** File mtimes and settings the rules were read under; a different key means read again. */
  key: string
  rules: RuleSet
  /** The files the rules came from, as /house-rules names them. */
  files: string[]
  errors: string[]
  isDefault: boolean
}

declare module 'claude-code' {
  interface PluginState {
    'house-rules': {
      loaded: LoadedRules | null
      blocks: Record<string, number>
      prompts: number
      toasted: string[]
      /** A compaction ran and the pinned rules have not been re-read since. */
      pinPending: boolean
    }
  }
}
